public class AnyOfValidator extends BaseJsonValidator {
    private List<JsonSchema> schemas;
    public AnyOfValidator(String schemaPath, JsonNode schemaNode, JsonSchema parentSchema, ValidationContext validationContext) {
        super(schemaPath, schemaNode, parentSchema, ValidatorTypeCode.ANY_OF);
        this.schemas = new ArrayList<>();
        if (schemaNode.isArray()) {
            for (JsonNode subSchemaNode : schemaNode) {
                JsonSchema schema = validationContext.newSchema(schemaPath, subSchemaNode, parentSchema);
                schemas.add(schema);
            }
        }
    }
    @Override
    public Set<ValidationMessage> walk(ExecutionContext executionContext, JsonNode node, JsonNode rootNode, String at, boolean shouldValidateSchema) {
        if (shouldValidateSchema) {
            return validate(executionContext, node, rootNode, at);
        }
        Set<ValidationMessage> errors = new LinkedHashSet<>();
        if (schemas != null) {
            for (JsonSchema schema : schemas) {
                errors.addAll(schema.walk(executionContext, node, rootNode, at, false));
            }
        }
        return errors;
    }
    // validate method etc.
}

